    "settings.providerAccounts.title": "AI Provider Accounts",
    "settings.providerAccounts.about": "Keep agent sign-ins separate and choose the account used by new terminals.",
    "settings.apiRouters.title": "API Routers",
    "settings.apiRouters.about": "Connect OpenRouter, AgentRouter, or custom endpoints and select models for terminals.",
    "settings.apiRouters.connectedTitle": "Connected Routers",
    "settings.apiRouters.connectedAbout": "Routers configured in ~/.zo/settings.json providers.",
    "settings.apiRouters.addTitle": "Add / Configure Router",
    "settings.apiRouters.addAbout": "Pick a preset or enter details to store API keys in Keychain and test connection.",
    "settings.apiRouters.preset": "Router Preset",
    "settings.apiRouters.customPreset": "Custom (User-defined)",
    "settings.apiRouters.name": "Name",
    "settings.apiRouters.baseUrl": "Base URL",
    "settings.apiRouters.apiKey": "API Key",
    "settings.apiRouters.keychainHint": "Keys are securely stored in the macOS Keychain; the settings file only stores the environment variable name.",
    "settings.apiRouters.noKeychainHint": "This computer has no keychain to keep an API key in. Only routers that need no key (such as Ollama) can be saved.",
